"""ML-DSA keys on a PKCS#11 3.2 token: generated by parameter set, read back by
CKA_PARAMETER_SET, exported as an RFC 9881 SubjectPublicKeyInfo built from
CKA_VALUE, signed with CKM_ML_DSA over the data itself.

The token is a stand-in that answers like one, signing through pyca. A real module
runs only when UCM_TEST_PKCS11_MLDSA_MODULE names one (SoftHSM 2.6 has no ML-DSA).
"""
import os

import pytest
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import mldsa

from services.hsm.base_provider import HsmOperationError
from services.hsm.pkcs11_provider import PKCS11_AVAILABLE
from utils import key_algorithms

pytestmark = [
    pytest.mark.skipif(not key_algorithms.mldsa_supported(), reason='this build has no ML-DSA'),
    pytest.mark.skipif(not PKCS11_AVAILABLE, reason='python-pkcs11 not installed'),
]

if PKCS11_AVAILABLE:
    import pkcs11
    from pkcs11 import Attribute, KeyType, Mechanism, ObjectClass
    from pkcs11.mechanisms import MLDSAParameterSet

    LEVELS = {
        'ML-DSA-44': (MLDSAParameterSet.ML_DSA_44, mldsa.MLDSA44PrivateKey),
        'ML-DSA-65': (MLDSAParameterSet.ML_DSA_65, mldsa.MLDSA65PrivateKey),
        'ML-DSA-87': (MLDSAParameterSet.ML_DSA_87, mldsa.MLDSA87PrivateKey),
    }
else:  # pragma: no cover
    LEVELS = {}


class _Object:
    """A token object: attributes by CKA, a missing one raises like a token does."""

    def __init__(self, attrs, key=None, calls=None):
        self.attrs, self.key, self.calls = attrs, key, calls

    def __getitem__(self, attribute):
        if attribute not in self.attrs:
            raise pkcs11.exceptions.AttributeTypeInvalid()
        return self.attrs[attribute]

    def sign(self, data, mechanism=None, mechanism_param=None):
        self.calls.append((mechanism, mechanism_param))
        if mechanism != Mechanism.ML_DSA:
            raise pkcs11.exceptions.MechanismInvalid()
        return self.key.sign(data)


class _Session:
    """Holds ML-DSA key pairs the way a PKCS#11 3.2 token does."""

    def __init__(self):
        self.objects, self.generated, self.sign_calls = [], [], []

    def add_pair(self, label, key_id=b'\x01', on_private=True, on_public=True):
        pset, cls = LEVELS[label]
        key = cls.generate()
        common = {Attribute.KEY_TYPE: KeyType.ML_DSA, Attribute.ID: key_id, Attribute.LABEL: label}
        public = {**common, Attribute.CLASS: ObjectClass.PUBLIC_KEY,
                  Attribute.VALUE: key.public_key().public_bytes_raw()}
        private = {**common, Attribute.CLASS: ObjectClass.PRIVATE_KEY, Attribute.SIGN: True}
        if on_public:
            public[Attribute.PARAMETER_SET] = pset
        if on_private:
            private[Attribute.PARAMETER_SET] = pset
        pub, priv = _Object(public), _Object(private, key, self.sign_calls)
        self.objects += [pub, priv]
        return pub, priv, key

    def get_objects(self, template):
        return [o for o in self.objects if all(o.attrs.get(a) == v for a, v in template.items())]

    def generate_keypair(self, key_type, key_length=None, **kwargs):
        self.generated.append((key_type, kwargs.get('mechanism'), kwargs.get('public_template')))
        pset = (kwargs.get('public_template') or {}).get(Attribute.PARAMETER_SET)
        label = next(name for name, (value, _cls) in LEVELS.items() if value == pset)
        pub, priv, _key = self.add_pair(label, key_id=kwargs['id'])
        return pub, priv


def _provider():
    from services.hsm.pkcs11_provider import Pkcs11Provider
    provider = Pkcs11Provider.__new__(Pkcs11Provider)
    provider._session, provider.list_errors = _Session(), []
    return provider


def _spki(pem):
    return serialization.load_pem_public_key(pem.encode())


@pytest.mark.parametrize('label', sorted(LEVELS))
def test_generation_asks_for_the_parameter_set_and_exports_rfc_9881_spki(label):
    provider = _provider()
    info = provider.generate_key(f'gen-{label}', label)
    key_type, mechanism, template = provider._session.generated[0]
    assert (key_type, mechanism) == (KeyType.ML_DSA, Mechanism.ML_DSA_KEY_PAIR_GEN)
    assert template[Attribute.PARAMETER_SET] == LEVELS[label][0]
    assert (info.algorithm, info.key_type) == (label, 'asymmetric')
    public = _spki(info.public_key_pem)
    assert key_algorithms.label_for_public_key(public) == label
    assert _spki(provider.get_public_key(info.key_identifier)) == public


@pytest.mark.parametrize('label', sorted(LEVELS))
def test_listing_reads_the_parameter_set(label):
    provider = _provider()
    provider._session.add_pair(label)
    [info] = provider.list_keys()
    assert (info.algorithm, info.purpose) == (label, 'signing')


def test_listing_reads_the_parameter_set_off_the_public_half():
    provider = _provider()
    provider._session.add_pair('ML-DSA-87', on_private=False)
    assert [k.algorithm for k in provider.list_keys()] == ['ML-DSA-87']


def test_sign_is_pure_ml_dsa_over_the_data():
    provider = _provider()
    _pub, _priv, key = provider._session.add_pair('ML-DSA-65')
    signature = provider.sign('01', b'tbs certificate', 'ML-DSA-65')
    key.public_key().verify(signature, b'tbs certificate')
    assert provider._session.sign_calls == [(Mechanism.ML_DSA, None)]


@pytest.mark.parametrize('extra', [{'hash_algorithm': 'sha256'}, {'padding': 'pss'}])
def test_sign_refuses_a_digest_or_padding(extra):
    provider = _provider()
    provider._session.add_pair('ML-DSA-65')
    with pytest.raises(HsmOperationError, match='ML-DSA'):
        provider.sign('01', b'tbs', 'ML-DSA-65', **extra)
    assert provider._session.sign_calls == []


SOFTHSM_LIB = '/usr/lib/softhsm/libsofthsm2.so'


def _release(lib_path):
    lib = getattr(pkcs11, '_loaded', {}).pop(lib_path, None)
    if lib is not None:
        lib.finalize()


@pytest.mark.skipif(not os.path.exists(SOFTHSM_LIB), reason='SoftHSM not installed')
def test_a_token_without_ml_dsa_refuses_generation_cleanly(tmp_path, monkeypatch):
    import subprocess
    from services.hsm.pkcs11_provider import Pkcs11Provider
    conf = tmp_path / 'softhsm2.conf'
    (tmp_path / 'tokens').mkdir()
    conf.write_text(f"directories.tokendir = {tmp_path / 'tokens'}\nobjectstore.backend = file\n"
                    "log.level = ERROR\n")
    monkeypatch.setenv('SOFTHSM2_CONF', str(conf))
    subprocess.run(['softhsm2-util', '--init-token', '--free', '--label', 'ucmpq',
                    '--so-pin', '1234', '--pin', '1234'], check=True, capture_output=True)
    _release(SOFTHSM_LIB)
    provider = Pkcs11Provider({'module_path': SOFTHSM_LIB, 'token_label': 'ucmpq', 'user_pin': '1234'})
    try:
        with provider:
            with pytest.raises(HsmOperationError, match='PKCS#11 error'):
                provider.generate_key('pq', 'ML-DSA-65')
    finally:
        _release(SOFTHSM_LIB)


REAL_MODULE = os.environ.get('UCM_TEST_PKCS11_MLDSA_MODULE')


@pytest.mark.skipif(not REAL_MODULE, reason='no PKCS#11 module with ML-DSA '
                    '(set UCM_TEST_PKCS11_MLDSA_MODULE, _TOKEN and _PIN)')
@pytest.mark.parametrize('label', sorted(LEVELS))
def test_real_module_generates_exports_and_signs(label):
    from services.hsm.pkcs11_provider import Pkcs11Provider
    provider = Pkcs11Provider({'module_path': REAL_MODULE,
                               'token_label': os.environ['UCM_TEST_PKCS11_MLDSA_TOKEN'],
                               'user_pin': os.environ['UCM_TEST_PKCS11_MLDSA_PIN']})
    with provider:
        info = provider.generate_key(f'ucm-pq-test-{label}', label)
        try:
            public = _spki(provider.get_public_key(info.key_identifier))
            assert key_algorithms.label_for_public_key(public) == label
            assert label in [k.algorithm for k in provider.list_keys()
                             if k.key_identifier == info.key_identifier]
            public.verify(provider.sign(info.key_identifier, b'tbs', label), b'tbs')
        finally:
            provider.delete_key(info.key_identifier)
